<?php
require dirname(__DIR__,2).'/api/accounts_post_delete_core.php';
function tt_post_correction_allowed($u,$j){return !empty($u['edit']);}function tt_user_can_access_entity($u,$e,$a){return !empty($u['edit'])&&$e==='TG';}function tt_next_post_id($rows,$m='Accounts',$a='Journal',$d=null){return 'REVERSE-'.count($rows);}
function check($v,$m){if(!$v)throw new RuntimeException($m);}
function journal($id,$type,$lines){return ['id'=>$id,'entity'=>'TG','sourceType'=>$type,'date'=>'2026-07-13','status'=>'Posted','lines'=>$lines,'narration'=>$id,'totalDebit'=>array_sum(array_column($lines,'debit')),'totalCredit'=>array_sum(array_column($lines,'credit'))];}
$opening=journal('OPEN','CARRY_FORWARD_OPENING',[['account'=>'1210','debit'=>100,'credit'=>0,'currency'=>'AED'],['account'=>'3400','debit'=>0,'credit'=>100,'currency'=>'AED']]);
$receipt=journal('RECEIPT','TG_BANK_RECEIPT',[['account'=>'1110','bankAccountId'=>'AED','debit'=>100,'credit'=>0,'bankDebit'=>100,'bankCredit'=>0,'currency'=>'AED'],['account'=>'1210','debit'=>0,'credit'=>100,'currency'=>'AED']]);
$s=['revision'=>3,'journals'=>['OPEN'=>$opening,'RECEIPT'=>$receipt],'exportCandidates'=>['C'=>['id'=>'C','entity'=>'TG','journalId'=>'OPEN','candidateType'=>'CUSTOMER_EXPORT_SALE','transactionAmount'=>100]],'tgBankTransactions'=>['T'=>['id'=>'T','journalId'=>'RECEIPT','kind'=>'Receipt','receiptType'=>'EXPORT_RECEIVABLE','sourceCandidateId'=>'C','settlementAmountNative'=>100,'status'=>'Accounts Approved / Posted']]];
$before=$s;try{apd_delete($s,['edit'=>false],'OPEN',['reason'=>'Wrong invoice']);throw new RuntimeException('Denied user accepted');}catch(DomainException $e){}check($s===$before,'Denial must be atomic');
$result=apd_delete($s,['edit'=>true],'OPEN',['reason'=>'Wrong invoice']);check($result['cancelledPostIds']===['RECEIPT','OPEN'],'Dependent receipt must cancel before opening');check($s['tgBankTransactions']['T']['status']==='Deleted'&&$s['exportCandidates']['C']['journalId']==='','Release receipt and recognized invoice links');check(count($result['impact'])===2&&count($result['sources'])===2,'Detailed impact includes all ledgers and registers');check($s['journals']['OPEN']['lines']===$opening['lines'],'Original lines are immutable');
$copy=$before;try{apd_delete($copy,['edit'=>true],'OPEN',['reason'=>'Wrong invoice','deletionFingerprint'=>'stale']);throw new RuntimeException('Stale confirmation accepted');}catch(DomainException $e){}check($copy===$before,'Stale confirmation must not mutate');
$preview=$before;$plan=apd_delete($preview,['edit'=>true],'OPEN',['reason'=>'Wrong invoice']);$copy=$before;$saved=apd_delete($copy,['edit'=>true],'OPEN',['reason'=>'Wrong invoice','deletionFingerprint'=>$plan['fingerprint']]);check($saved['cancelledPostIds']===$result['cancelledPostIds'],'Confirmed impact matches preview');
echo "PASS TG deletion: dependent receipt cascade, reopened source balances, detailed native impact, immutable history, permissions and stale confirmation\n";
